cross join (values ($c$Getting started$c$, $c$getting-started$c$, 1), ($c$Trips and budgets$c$, $c$trips-and-budgets$c$, 2), ($c$Expenses and receipts$c$, $c$expenses-and-receipts$c$, 3), ($c$Splitting and settling up$c$, $c$splitting-and-settling-up$c$, 4), ($c$Insights and checks$c$, $c$insights-and-checks$c$, 5), ($c$Map and places$c$, $c$map-and-places$c$, 6), ($c$Plans and account$c$, $c$plans-and-account$c$, 7)) as c(name, slug, ord)
where p.slug = $c$zotikos$c$
