insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$start-your-first-trip$c$, $c$Start your first trip$c$, $c$Sign in with an email code (or try it as a guest), choose your home currency, then make a trip and add who's coming. Then find your way around.$c$, $c$[{"type":"callout","title":"The short version","text":"Open **zotikosapp.midnightpoetry.studio**, sign in, choose your home currency and tap **New trip**. Add travellers by name; you can invite them by link later."},{"type":"heading","text":"1. Sign in"},{"type":"paragraph","text":"New here? Under “New to Zotikos?”, tap **Create a free account**, enter your email and a password of at least 12 characters (twice), and tap **Create account**. Then open the email we send and tap **Confirm my email**, come back and sign in with your email and password."},{"type":"paragraph","text":"After that, signing in is usually just **Email me a code**: a 6-digit code that works once and expires in 10 minutes. Your password is the backup if a code doesn't arrive."},{"type":"paragraph","text":"Just want to look around? Tap **Try as guest** when it's offered. Guest trips work the same way with smaller limits: one active trip, up to four travellers and no invite links. You can keep them later by adding your email (see [Sign-in, security and your data](/guides/zotikos/sign-in-security-and-your-data))."},{"type":"heading","text":"2. Choose your home currency"},{"type":"paragraph","text":"Zotikos asks “Which currency is home?”. Pick the currency your bank account or card is in; a suggestion from your device's region is at the top, and you can search by country or code. New trips keep their balances in it. Changing it later only affects new trips, so nobody's balance shifts."},{"type":"heading","text":"3. Make a trip"},{"type":"list","ordered":true,"items":["Tap **New trip**.","Give it a **Trip name**, such as “Kyoto & Seoul”.","Optionally choose a **Country**. Picking one sets the currency below, and you can still change it.","Check **Balances kept in**. It starts as your home currency, and everyone settles up in this. Spending can still be in any currency.","Add **Starts** and **Ends** dates and a budget if you like. They're all optional (see [Daily and whole-trip budgets](/guides/zotikos/daily-and-whole-trip-budgets)).","Under **Who's coming**, type a name in the box, and tap **Add a traveller** for another box. You're already on the trip.","Tap **Create trip**."]},{"type":"paragraph","text":"Making a trip needs a connection. Once it exists, you can add expenses offline."},{"type":"heading","text":"4. Log the first expense"},{"type":"paragraph","text":"On a phone or tablet, tap **Add expense** on the trip and choose **Scan a receipt**, **Add by item** or **Just the total**. On a computer, use **Add expense** (**Add by item** or **Just the total**) or **Upload receipt**. See [Add an expense in any currency](/guides/zotikos/add-an-expense-in-any-currency)."},{"type":"heading","text":"Finding your way around"},{"type":"table","caption":"","header":["Where","What you'll see"],"rows":[["Phone, outside a trip","A bottom bar with Trips, Insights and Account."],["Phone, inside a trip","Overview, Ledger, Map, Settle up and Insights along the bottom. At the top: **‹ Trips**, a faces icon for People, and a gear for Trip settings."],["Tablet","The same tabs in a slim bar down the side, with People and Settings."],["Computer","A sidebar: Trips, Insights, Account; inside a trip also Overview, Ledger, Map, Settle up, People and Trip settings, plus a “Switch trip” picker. On the Overview, press N to add, / to search."],["Add expense","A floating button on phones and tablets. It's hidden on the Map tab and on archived trips."]]},{"type":"faq","items":[{"q":"Do my travel buddies need the app?","a":"No. Add them by name and log everything yourself. If they'd like to see the trip and add expenses from their own phone, send an invite link: see [People, invite links and co-owners](/guides/zotikos/invite-travellers-with-a-link)."},{"q":"What happens to guest trips if I sign out?","a":"Guest trips belong to that guest session on that device. Before signing out, open **Account**, go to **Keep your trips**, enter your email, tap **Send me a code**, type the 6-digit code and tap **Keep my trips**. If that email already has an account, you can choose **Sign in and bring my trips** to move them into it."},{"q":"No code arrived?","a":"Check spam or promotions, then tap **Send a new code** (you can ask again after 30 seconds), or sign in with your password instead. If you haven't made an account yet, the code screen offers **Create one with this email**."}]},{"type":"cta","title":"Go anywhere. Come home all square.","text":"Free to start, in your browser.","label":"Open Zotikos","url":"https://zotikosapp.midnightpoetry.studio/"}]$c$::jsonb, true, $c$Start your first trip | Zotikos$c$, $c$Create a Zotikos account or try it as a guest, choose your home currency, make a trip, add travellers, log the first expense and learn where everything is.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$getting-started$c$
where p.slug = $c$zotikos$c$
on conflict (product_id, slug) do update set category_id = excluded.category_id, title = excluded.title, standfirst = excluded.standfirst, blocks = excluded.blocks, start_here = excluded.start_here,
