  where public.guides.updated_by is null;

insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$install-zotikos-and-use-it-offline$c$, $c$Install Zotikos and use it offline$c$, $c$Zotikos runs in your browser, with no app store. Add it to your home screen and it opens full screen and keeps working when there's no signal.$c$, $c$[{"type":"callout","title":"The short version","text":"Install it from your browser, then log expenses anywhere. Changes you make offline wait on your phone and sync on their own when you're back online."},{"type":"heading","text":"Install it"},{"type":"table","caption":"","header":["Device","Browser","How"],"rows":[["iPhone & iPad","Safari","Share → Add to Home Screen → Add"],["Android","Chrome","Tap **Install** on the Install Zotikos card, or ⋮ → Install app"],["Mac & PC","Chrome or Edge","Click the install icon in the address bar"]]},{"type":"paragraph","text":"Installed, Zotikos opens full screen like any other app."},{"type":"heading","text":"What works offline"},{"type":"list","ordered":false,"items":["Opening trips you've already viewed (the trip shows an **Offline** note with the date of its saved rates)","Adding, editing and deleting expenses, including a place for each expense","Marking payments as paid in **Settle up**","Taking receipt photos: they wait on your phone, and you tap the “receipt photos waiting” card on the trip when you're back online"]},{"type":"paragraph","text":"These need a connection: making a new trip, trip settings, People (adding, renaming or removing travellers, invite links and co-owners), changing a trip's currency and **Pay it in**, the Ledger's “Needs a look” buttons, CSV export, your account and picture, Pro, reading a receipt, and searching for a place. A trip you've never opened on this device isn't available offline."},{"type":"heading","text":"How syncing works"},{"type":"paragraph","text":"On the Trips screen a chip shows **Offline** and how many changes are waiting, then **Syncing**, then **Synced**. Inside a trip, the cloud icon at the top shows the same thing (on a computer it's a line of text: offline, N waiting to sync, or synced just now). You don't need to do anything: waiting changes are sent in the order you made them when you're back online."},{"type":"paragraph","text":"If a change is turned down (for example, the trip has reached its plan's number of expenses), it stays in a **Waiting to sync** card in the ledger with the reason, and you can **Discard** it. If two people change the same expense, the last change to arrive is the one that's kept."},{"type":"heading","text":"Exchange rates offline"},{"type":"paragraph","text":"Offline, Zotikos converts with the last rates it saved and says so, for example “rates from 27 oct”. That's a preview: when the expense syncs, it's converted at the latest reference rate. To keep a rate of your own, tick **Use my own rate**. More in [How exchange rates work in Zotikos](/guides/zotikos/how-exchange-rates-work)."},{"type":"heading","text":"Clearing the offline copy"},{"type":"paragraph","text":"In **Account**, under **This device**, **Offline copy** has a **Clear** button that removes this device's saved copy. Like signing out, it also discards any changes and receipt photos still waiting to sync, so let them finish first."},{"type":"faq","items":[{"q":"The map shows no streets offline. Is that normal?","a":"Yes. Your pins and places list still come from the copy on your device, but map tiles aren't saved for offline use."},{"q":"How do I get the newest version?","a":"When one is ready you'll see “A new version of Zotikos is ready.” Tap **Reload**."}]},{"type":"cta","title":"Log it on the mountain.","text":"Syncs when you're back.","label":"Open Zotikos","url":"https://zotikosapp.midnightpoetry.studio/"}]$c$::jsonb, false, $c$Install Zotikos and use it offline | Zotikos$c$, $c$Add Zotikos to your home screen on iPhone, Android or a computer, and see what works offline and how changes sync when you're back.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$getting-started$c$
where p.slug = $c$zotikos$c$
