  where public.guides.updated_by is null;

insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$invite-travellers-with-a-link$c$, $c$People, invite links and co-owners$c$, $c$Anyone you add by name is already part of the split. An invite link lets them see the trip and add expenses from their own phone. A co-owner can help run it.$c$, $c$[{"type":"callout","title":"The short version","text":"Open **People** on the trip (the faces icon at the top, or People in the sidebar), tap **Create invite link** and **Share** it. Each person opens it, signs in and picks which name is them. A link lasts 14 days and works up to 20 times."},{"type":"heading","text":"The People screen"},{"type":"paragraph","text":"People lists everyone on the trip with whether they've **Joined** or are “Not joined yet · added by name”, and what they paid, their share and their balance. Owners and co-owners have a chip. Travellers you added by name get a **Send invite** button."},{"type":"heading","text":"Add someone by name"},{"type":"paragraph","text":"Tap **Add** (on a computer, **Add by name**) and type a name. They're included in splits straight away, even if they never open Zotikos."},{"type":"heading","text":"Create a link"},{"type":"list","ordered":true,"items":["Open **People** and tap **Create invite link** (or **Invite with a link**).","Tap **Share** to send it through any app. Where sharing isn't available, the link is copied for you."]},{"type":"paragraph","text":"Only the owner or a co-owner can create links, and they need an account. Guests add people by name only."},{"type":"heading","text":"Joining a trip"},{"type":"paragraph","text":"Your friend opens the link and signs in or creates an account; Zotikos remembers the link for 30 minutes while they do, even if the confirmation email opens in a new tab. They then see who invited them and choose which name is theirs, or **I'm not listed · join as someone new**, and tap **Join the trip**. Picking a name keeps everything already logged under it."},{"type":"paragraph","text":"If they're already on the trip, they see “You're already on this trip.” with a button to open it."},{"type":"heading","text":"Managing links"},{"type":"paragraph","text":"Each link shows how many times it's been used and when it expires, for example “Used 0/20 · expires …”. Tap **Turn off** to stop it working. If someone sees “This invite has expired or was already used.”, create a new link. Links stop working when a trip is archived."},{"type":"heading","text":"Co-owners"},{"type":"paragraph","text":"The owner can share the running of a trip. On **People**, open a traveller's options (the ⋯ button) and switch on **Co-owner**. A co-owner can do everything the owner can: change settings and budgets, manage travellers and invites, archive the trip and edit anyone's expenses. Only the owner can delete the trip or choose co-owners. Only someone who has joined with an account can be a co-owner, so send them an invite first."},{"type":"heading","text":"Who can do what"},{"type":"table","caption":"","header":["Action","Who"],"rows":[["Add a traveller by name","Anyone on the trip"],["Add an expense or mark a payment","Anyone on the trip"],["Edit or delete an expense","Whoever added it, the owner and co-owners; everyone, if **Everyone can edit expenses** or **Everyone can delete expenses** is on in Trip settings › Permissions (off by default)"],["Rename a traveller","The owner; a co-owner (anyone except the owner); everyone else can rename themselves or a name nobody has joined as. Tap ⋯ next to the name, then **Save name**"],["Remove a traveller","The owner or a co-owner, if that person has no expenses, shares or payments (only the owner can remove a co-owner). Tap ⋯, then **Remove from trip**"],["Change details, budgets, trip currency, invite links, archive or restore","The owner or a co-owner"],["Delete the trip, choose co-owners","The owner only"]]},{"type":"paragraph","text":"People also has a **Who can do what** card that shows the current rules, with a **Change** link."},{"type":"faq","items":[{"q":"Can people on the trip see my email?","a":"No, never your full email. They see your name on the trip. If you haven't set a name in **Account**, the part of your email before the @ is used, so set your **Name** first."},{"q":"How many people can join?","a":"It depends on the trip owner's plan: 4 on a guest trip, 8 on Free and 50 on Pro when this was written. **New trip** and **People** show the limit for your own plan. See [Guest, Free and Pro](/guides/zotikos/guest-free-and-pro)."}]},{"type":"cta","title":"Everyone sees the same ledger.","text":"","label":"Open Zotikos","url":"https://zotikosapp.midnightpoetry.studio/"}]$c$::jsonb, false, $c$People, invite links and co-owners | Zotikos$c$, $c$Add travellers, send an invite link, make a co-owner, and see who can edit, delete, rename or remove what on a Zotikos trip.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$trips-and-budgets$c$
