insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$daily-and-whole-trip-budgets$c$, $c$Daily and whole-trip budgets$c$, $c$Set a daily budget for your own share and, on Free and Pro, a budget for the whole group. The trip's home screen shows how today is going at a glance.$c$, $c$[{"type":"callout","title":"The short version","text":"Add budgets when you make the trip, or later in **Trip settings › Money**. The **Today** card shows what's left of today's budget for your share, whether you're on pace, and what has rolled over from earlier days."},{"type":"heading","text":"Setting a budget"},{"type":"list","ordered":false,"items":["**Daily budget (your share)**: what you can spend per day, counting only your share of each expense.","**Whole-trip budget (whole group)**: a total for everyone's spending on the trip. Free and Pro."]},{"type":"paragraph","text":"Both are optional and in the trip's currency. There's one of each per trip, set by the owner or a co-owner under **Trip settings › Money**, and every traveller's own share is measured against the daily one. Not an owner or co-owner? Ask them to set it."},{"type":"heading","text":"Reading the Today card"},{"type":"list","ordered":false,"items":["The big number: today's budget plus what rolled over, minus your share today, shown as **left** or **over**.","The meter and its note: **on pace**, **close to today's ceiling** (past 85%) or **over today's ceiling**.","**Rolled over**: what you were under (or over) your daily budget on earlier days since the trip's start date. It needs a start date, and days after the end date don't earn budget.","**Trip**: on a phone, the percentage of the whole-trip budget the group has used. On a computer, the **Trip spend** card shows the group's total, for example “of … group budget · 40% used”, with your own share on a separate line."]},{"type":"paragraph","text":"No daily budget yet? The card shows your share today, with a **Set a daily budget** link. On the trips list, each active trip with a daily budget shows **Left today**, or **Over today**."},{"type":"heading","text":"Where the money went"},{"type":"paragraph","text":"**Your share by category** on the trip shows your share in the eight categories: Food, Groceries, Stay, Flights, Transport, Activities, Shopping and Other. **Insights** goes further. Under **Will we stay on budget?**, **Your own pace** shows what you average, your daily budget and what's carried into today. Under **When was the money spent?**, **Each day** charts every day (it needs an account, so guests don't see it). See [Insights: four questions about your trip](/guides/zotikos/insights-on-a-trip)."},{"type":"paragraph","text":"A stay or pass that covers several days is spread evenly across its days for these budgets. See [Add an expense in any currency](/guides/zotikos/add-an-expense-in-any-currency)."},{"type":"heading","text":"If you change the trip's currency"},{"type":"paragraph","text":"Budgets move to the new currency at today's rate, whichever option you choose. See [How exchange rates work in Zotikos](/guides/zotikos/how-exchange-rates-work)."},{"type":"faq","items":[{"q":"Does the daily budget count what I paid for others?","a":"No. It counts your share of each expense, so paying for the whole dinner only uses your part of it."},{"q":"Who can change the budgets?","a":"The trip's owner or a co-owner, in **Trip settings**."}]},{"type":"cta","title":"Know what's left today.","text":"","label":"Open Zotikos","url":"https://zotikosapp.midnightpoetry.studio/"}]$c$::jsonb, false, $c$Daily and whole-trip budgets | Zotikos$c$, $c$Set a daily budget for your share and a whole-trip budget for the group, and read the Today card: what's left, whether you're on pace and what rolled over.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$trips-and-budgets$c$
where p.slug = $c$zotikos$c$
