insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$archive-restore-or-delete-a-trip$c$, $c$Archive, restore, export or delete a trip$c$, $c$Back home? Archive the trip to keep a read-only copy and free an active-trip slot, export it as a spreadsheet, or delete it for everyone.$c$, $c$[{"type":"callout","title":"The short version","text":"Open **Trip settings**. **Export** and **Archive or delete** are near the bottom. Archiving keeps the trip but makes it read-only; deleting removes it for everyone and can't be undone. The owner or a co-owner can archive and restore; only the owner can delete."},{"type":"heading","text":"Archive a trip"},{"type":"paragraph","text":"Next to **Archive trip** (“Read-only, frees an active-trip slot”), tap **Archive**. Everyone on the trip sees “This trip is archived and read-only. Restore it from trip settings to add more.” The Add expense button disappears, and invite links stop working. To add more later, tap **Restore** next to **Restore trip**."},{"type":"paragraph","text":"Free includes two active trips at a time. When you reach that, the trips list suggests archiving one or going Pro. Restoring needs a free slot too. Guests can't archive trips."},{"type":"heading","text":"How long archived trips are kept"},{"type":"table","caption":"Limits when this guide was written; they can change.","header":["Plan","Archived trips","Kept for"],"rows":[["Free","Up to 10","1 year after you archive it"],["Pro","Unlimited","As long as you have Pro"]]},{"type":"paragraph","text":"After that time, archived trips are deleted automatically, so export anything you want to keep. On a computer, the Trips dashboard has filters for All, On the road, Upcoming, Past and Archived."},{"type":"heading","text":"Export a trip"},{"type":"paragraph","text":"Anyone on the trip can export it: next to **Export as CSV**, tap **CSV** (computers also have **Export CSV** on the Ledger). You get a spreadsheet with one row per expense: the date, the last day of a several-day expense (**Until**), description, category, who paid, the currency and amount, the amount in the trip's currency, the rate and rate date, the place name, address and coordinates if one was saved, and each person's share. Payments aren't included. It counts against your own plan: Free includes five exports a month, Pro is unlimited and guests get none."},{"type":"heading","text":"Delete a trip"},{"type":"paragraph","text":"Next to **Delete trip**, tap **Delete** and confirm. The trip, its expenses and its payments are deleted for everyone on it. This can't be undone."},{"type":"faq","items":[{"q":"Can someone else archive or delete my trip?","a":"A co-owner you chose can archive and restore it, but only you, as the owner, can delete it."},{"q":"Why can't I restore a trip?","a":"Restoring makes it active again, so it needs a free active-trip slot. Archive another trip first, or go Pro."}]},{"type":"cta","title":"Home all square.","text":"","label":"Open Zotikos","url":"https://zotikosapp.midnightpoetry.studio/"}]$c$::jsonb, false, $c$Archive, restore, export or delete a trip | Zotikos$c$, $c$Archive a finished trip to free an active slot, restore it later, export it as CSV, or delete it for everyone. Plus how long archived trips are kept.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$trips-and-budgets$c$
where p.slug = $c$zotikos$c$
