insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$add-an-expense-in-any-currency$c$, $c$Add an expense in any currency$c$, $c$Choose Scan a receipt, Add by item or Just the total, enter what it cost in the currency you paid, and Zotikos converts it, splits it and updates everyone's balance.$c$, $c$[{"type":"callout","title":"The short version","text":"Tap **Add expense** and choose **Just the total**, **Add by item** or **Scan a receipt**. For a total, enter the **Amount** and its currency, say what it was for, then pick a category, who paid and how to split, and tap **Save expense**."},{"type":"heading","text":"Three ways to add"},{"type":"list","ordered":false,"items":["**Just the total**: one amount, the form described below.","**Add by item**: type each item and its price, and the total adds itself up.","**Scan a receipt**: photograph it and Zotikos reads it. See [Read a receipt from a photo](/guides/zotikos/read-a-receipt-from-a-photo)."]},{"type":"paragraph","text":"On a phone or tablet the sheet is titled “Add to {trip}” and offers all three. On a computer, **Add expense** offers **Add by item** and **Just the total**, and **Upload receipt** is the way to scan. Outside a trip, if two trips are on today, Zotikos asks “Which trip is it for?”."},{"type":"heading","text":"The fields"},{"type":"table","caption":"","header":["Field","What to put"],"rows":[["Amount","What was paid. Tap the currency to change it; Zotikos starts with the last one you used. Pasting something like “VND 120,000”, “S$12.50” or “1.234,56 €” keeps the number and sets the currency."],["What for","A short description, like “Ramen for three”. A “Looks like …” chip may suggest a category; tap it to use it."],["Category","Food, Groceries, Stay, Flights, Transport, Activities, Shopping or Other. A line above the picker says what each one covers."],["Paid by","Who paid. You show as “You”."],["Split","Opens a sheet to choose who shares it and how. Tap **Save split** when it's right."],["Paid with","Cash or Card."],["The date","Today, unless you change it. Tap it for “When was it?”."],["Place","Optional: where it was. See [Add where an expense was](/guides/zotikos/add-where-an-expense-was)."]]},{"type":"paragraph","text":"For splitting, see [Five ways to split an expense](/guides/zotikos/five-ways-to-split-an-expense)."},{"type":"heading","text":"Add by item"},{"type":"paragraph","text":"On “Add the details”, type each item and its price. Tap **Add tax, service or discount** for extras, and check the merchant, date, total and currency. At the bottom, choose **Split equally** or **Split by item**. If you'd rather scan, tap **Read a receipt instead**."},{"type":"heading","text":"Expenses that cover several days"},{"type":"paragraph","text":"A hotel stay or a transport pass? Tap the date, choose **Several days** and pick the first and last day (up to 92 days). Balances use the full amount once. Daily budgets, Insights and day totals spread it evenly across the days. In the Ledger it carries a tag such as “↦ 26–28 Oct · 3 days”."},{"type":"heading","text":"Picking a currency"},{"type":"paragraph","text":"Zotikos knows 153 currencies. Search by code, name or country; the currencies already used on this trip come first. How many different currencies a trip can use depends on the trip owner's plan (Free: five, including the trip's own currency)."},{"type":"heading","text":"Checking the conversion"},{"type":"paragraph","text":"Under the amount you'll see the converted total and the rate, for example “≈ USD 28.66 · 1 JPY = 0.006697 USD · live”. A rate you typed says “your rate”, and offline it says something like “rates from 27 oct”. If you got a different rate, tick **Use my own rate** and type it in. More in [How exchange rates work in Zotikos](/guides/zotikos/how-exchange-rates-work)."},{"type":"heading","text":"Edit or delete"},{"type":"paragraph","text":"Open the expense from the **Ledger** (on a computer, select it and tap **Edit**), change anything and tap **Save changes**, or tap **Delete expense**. Everyone's balances update. You can change or delete an expense if you added it, or you're the owner or a co-owner, or the trip allows everyone to (see [People, invite links and co-owners](/guides/zotikos/invite-travellers-with-a-link)). Otherwise you'll see “Someone else added this expense. Only they, the trip owner or a co-owner can change it …”."},{"type":"faq","items":[{"q":"Can I add expenses without signal?","a":"Yes. You'll see “Saved on this device · syncs when you're online”."},{"q":"Someone else paid. Can I log it?","a":"Yes. Choose them under **Paid by**."},{"q":"What's the card fee field?","a":"With Pro, choosing **Card** lets you add your card's foreign-transaction fee as a percentage (**Card foreign-transaction fee**), so **Insights** can show what card fees cost you."}]},{"type":"cta","title":"Spend in yen. Think in yours.","text":"","label":"Open Zotikos","url":"https://zotikosapp.midnightpoetry.studio/"}]$c$::jsonb, true, $c$Add an expense in any currency | Zotikos$c$, $c$Log an expense in any of 153 currencies: Just the total, Add by item or Scan a receipt. Category, who paid, how to split, several days, editing and deleting.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$expenses-and-receipts$c$
where p.slug = $c$zotikos$c$
