insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$how-exchange-rates-work$c$, $c$How exchange rates work in Zotikos$c$, $c$Where the rates come from, which rate an expense uses, how to use your own rate, and what happens if you change a trip's currency.$c$, $c$[{"type":"callout","title":"The short version","text":"Zotikos uses daily reference rates. An expense in another currency is converted at the latest rate when it's saved, and that rate is stored with it. Tick **Use my own rate** to type the rate you actually got."},{"type":"heading","text":"Where the rates come from"},{"type":"paragraph","text":"Once a day, Zotikos fetches reference rates (from Frankfurter, with a public backup feed), checks them and keeps a snapshot. Your browser never contacts a rate provider. Reference rates are wholesale rates, so your bank or card may have charged a little more."},{"type":"heading","text":"Which rate an expense gets"},{"type":"list","ordered":false,"items":["**Same currency as the trip**: no conversion (“In the trip's currency”).","**Another currency**: converted at the latest reference rate when the expense is saved, and that rate is stored with it.","**Your own rate**: tick **Use my own rate** and type it in as 1 of the currency you paid = … of the trip's currency. It's kept exactly, including when you edit the expense later."]},{"type":"callout","title":"Good to know","text":"The reference rate is the latest one when you save, not the rate on the expense's date. Saving changes to an expense in another currency converts it again at the latest rate, unless it uses your own rate."},{"type":"heading","text":"Offline"},{"type":"paragraph","text":"Without signal, Zotikos shows a conversion from its last saved rates and labels it, for example “rates from 27 oct”. When the expense syncs, it's converted at the latest reference rate. If there's no saved rate for that currency yet, you'll be asked to type the rate in."},{"type":"heading","text":"A typed rate that looks off"},{"type":"paragraph","text":"The Ledger's **Needs a look** card flags a typed rate that's more than 3% away from that day's reference rate. It says “A card or exchange-counter rate can be right, so this is only a check.” Tap **Keep typed rate** if it's right, or **Change the rate** to fix it. More in [Needs a look: checks in the Ledger](/guides/zotikos/needs-a-look-checks-in-the-ledger)."},{"type":"heading","text":"Changing a trip's currency"},{"type":"paragraph","text":"The owner or a co-owner can change a trip's currency later, online, under **Trip settings › Money** (not on archived trips). If the trip already has expenses or payments, Zotikos asks how to treat them:"},{"type":"list","ordered":false,"items":["**Keep them in** the old currency: balances and Settle up show a line for each currency, and new expenses use the new one.","**Convert them to** the new currency: everything is converted at today's rate, so there's one line and what everyone owes stays the same."]},{"type":"paragraph","text":"Budgets move to the new currency at today's rate either way. If older lines are left, **Settle up** shows them separately with a **Pay it in** button that moves the amount onto the new line at today's rate. If you set a **Country** that uses another currency, Trip settings offers **Keep balances in** that currency."},{"type":"heading","text":"Seeing the rate later"},{"type":"paragraph","text":"On a computer, select an expense in the **Ledger** to see the **Rate used**. A trip's CSV export lists each expense's rate and rate date (see [Archive, restore, export or delete a trip](/guides/zotikos/archive-restore-or-delete-a-trip))."},{"type":"heading","text":"Exchange-rate gain or loss (Pro)"},{"type":"paragraph","text":"With Pro, **Insights › How did you pay?** has a **Paying abroad** card. Its “What the rates did since you paid” line compares the rate each expense was counted at (see above) with today's rate, per currency and overall. It isn't money lost, and it's kept apart from card fees on purpose."},{"type":"faq","items":[{"q":"Which currency are balances in?","a":"The trip's currency, chosen under **Balances kept in** when the trip was made (it defaults to your home currency or your chosen country's). The owner or a co-owner can change it later."},{"q":"My bank charged a different amount. What should I do?","a":"Open the expense, tick **Use my own rate** and type the rate from your statement, then tap **Save changes**."}]},{"type":"cta","title":"Every currency, one ledger.","text":"","label":"Open Zotikos","url":"https://zotikosapp.midnightpoetry.studio/"}]$c$::jsonb, false, $c$How exchange rates work | Zotikos$c$, $c$Zotikos converts with daily reference rates and stores the rate with each expense. Learn which rate is used, your own rate, offline rates and changing a trip's currency.$c$, 'Midnight Poetry Studio', 'published'
