insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$read-a-receipt-from-a-photo$c$, $c$Read a receipt from a photo$c$, $c$Take a photo of a receipt and Zotikos fills in the merchant, date, items, tax and currency, checks the maths and lets you fix anything before saving. The photo isn't kept.$c$, $c$[{"type":"callout","title":"The short version","text":"Tap **Add expense**, then **Scan a receipt**. Point the camera, tap the shutter, check the details, tap **Split equally** or **Split by item**, and save the expense."},{"type":"heading","text":"Taking the photo"},{"type":"list","ordered":true,"items":["On a phone, tap **Add expense** and choose **Scan a receipt**. On a computer, use **Upload receipt** on the trip, **Scan receipt** on the Trips list, or **Read receipt** at the top of a new expense.","Lay the receipt flat in good light. The camera says “Point at the receipt · Zotikos frames it for you”, then “Receipt found · hold steady and tap”.","Tap the round shutter. Use the torch button if your browser offers one, or **Photos** to pick a photo you already have."]},{"type":"paragraph","text":"A photo you pick opens a crop view (“Drag the corners to fit the receipt”). Drag the corners, then tap the check button to read it, or **Cancel**. If the camera is off, the shutter opens your phone's own camera instead. **Type it in** opens the choices for adding by hand."},{"type":"paragraph","text":"While it works you'll see messages such as “Reading the receipt…”. Long receipts can take a little longer."},{"type":"heading","text":"Check the details"},{"type":"paragraph","text":"On **Check the details** you can fix the merchant, date, currency and **Total paid**, edit or remove items, and tap **Add tax, service or discount**. If the numbers don't add up, Zotikos says what's off, for example “Items plus charges is …, but the total says …”, and may offer one-tap fixes such as “Use … as the total” or “Add … as an item”. When it's right, “{n} items add up to {total}”. Tap **Retake** if the read was poor."},{"type":"paragraph","text":"At the bottom, choose **Split equally** or **Split by item**. This takes you to the expense, which you then save; item by item opens the Split sheet straight away (see [Five ways to split an expense](/guides/zotikos/five-ways-to-split-an-expense))."},{"type":"heading","text":"What happens to the photo"},{"type":"paragraph","text":"On your phone the photo is turned upright, made smaller and saved again as a plain image, which removes its location and camera details. It's read and then thrown away; Zotikos never stores receipt photos. Only the details you save with the expense are kept."},{"type":"heading","text":"How many reads you get"},{"type":"table","caption":"Limits when this guide was written; they can change.","header":["Plan","Receipt reads"],"rows":[["Guest","3 a day"],["Free","10 a month"],["Pro","200 a month"]]},{"type":"paragraph","text":"The camera shows how many you have left (for example “7 of 10 reads left”). If a read fails on Zotikos's side, you get it back; a photo that simply can't be read (blurry, cut off, not a receipt) still counts. When you run out you'll see “You've used all your receipt reads for now. You can still type the expense in.”"},{"type":"heading","text":"No signal?"},{"type":"paragraph","text":"Take the photo anyway. It waits on your phone (up to 3 photos as a guest, 20 on Free, 50 on Pro), and the trip's Overview shows a “receipt photos waiting” card. Once you're online, tap it to **Read them now**; the trip's photos are read one at a time, oldest first."},{"type":"faq","items":[{"q":"It couldn't read my receipt.","a":"Try a flatter, brighter photo with the whole receipt in the frame, or tap **Type it in**."},{"q":"Where is a photo kept while it waits offline?","a":"Only on your phone, in the browser's storage, until it's read."}]},{"type":"cta","title":"Snap it. It reads itself.","text":"","label":"Open Zotikos","url":"https://zotikosapp.midnightpoetry.studio/"}]$c$::jsonb, false, $c$Read a receipt from a photo | Zotikos$c$, $c$Photograph a receipt to fill in the merchant, date, items, tax and currency, check the maths, then split. Plus read limits, privacy and offline photos.$c$, 'Midnight Poetry Studio', 'published'
