insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$five-ways-to-split-an-expense$c$, $c$Five ways to split an expense$c$, $c$Equally, exact amounts, percentages, shares or item by item. Whichever you choose, Zotikos rounds to the cent so the shares always add up to the total.$c$, $c$[{"type":"callout","title":"The short version","text":"On the expense, tap the **Split** row to open the Split sheet. Choose a method and who's in. When it's right, the line underneath says “Adds up to …”; if not, it tells you what's still to assign. Tap **Save split**."},{"type":"heading","text":"The methods"},{"type":"table","caption":"","header":["Method","How it works","Plans"],"rows":[["Equally","Tick who's in; everyone pays the same.","All"],["Exact amounts","Type each person's amount.","All"],["Percentages","A percentage each, up to two decimals, adding up to 100%.","Pro, or a free try"],["Shares","Whole-number shares with − and +, e.g. 2 for someone who had twice as much.","Pro, or a free try"],["Item by item","Add each item (typed or read from a receipt) and give it to the people who had it.","Pro, or a free try"]]},{"type":"paragraph","text":"In the sheet the methods are short labels: Equal, Exact, %, Shares and Items."},{"type":"heading","text":"Free tries"},{"type":"paragraph","text":"On Free you get two free tries per trip, shared between percentages, shares and item by item. The sheet tells you when a method is a Pro feature, how many tries each trip has and how many you've used. Guests can split equally or by exact amounts."},{"type":"heading","text":"Item by item"},{"type":"paragraph","text":"Choose **Add by item** and type the items, or scan a receipt and tap **Split by item**. In the Split sheet's items mode, each item has a name and a price, and you choose who had it. An item shared by several people is split equally between them, and tax, service charges and discounts are shared in proportion to what each person had."},{"type":"paragraph","text":"The items must add up to the amount: “The items come to … but the amount is …. Make them match to save.” The total follows the items unless you typed a different amount."},{"type":"heading","text":"How the rounding works"},{"type":"paragraph","text":"Money is counted in whole cents. Each share is worked out exactly and rounded down, then the leftover cents go one at a time to whoever was closest to the next cent, with ties going to the payer first. So if three people split 10.00 and the payer is one of them, the payer's share is 3.34 and the others' are 3.33. The total is always exact."},{"type":"paragraph","text":"Converted shares are rounded the same way, so they always add up to the converted total."},{"type":"faq","items":[{"q":"What does “Amounts still … to assign” mean?","a":"The exact amounts you've typed add up to less than the expense. Give the difference to someone, or check the total."},{"q":"How many people can share one expense?","a":"It depends on the trip owner's plan: up to 4 on a guest trip, 8 on Free, and everyone on the trip when the owner has Pro."}]},{"type":"cta","title":"Split it to the cent.","text":"","label":"Open Zotikos","url":"https://zotikosapp.midnightpoetry.studio/"}]$c$::jsonb, true, $c$Five ways to split an expense | Zotikos$c$, $c$Split equally, by exact amounts, percentages, shares or item by item, and see how Zotikos rounds so shares always add up. Plus free tries.$c$, 'Midnight Poetry Studio', 'published'
