insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$settle-up-with-fewer-transfers$c$, $c$Settle up with fewer transfers$c$, $c$Zotikos nets everyone's balances so nobody pays someone who then pays someone else. Pay through your own bank app, Wise or PayPal, then mark it as paid.$c$, $c$[{"type":"callout","title":"The short version","text":"Open **Settle up** on the trip. Under **You pay**, tap **Pay**, send the money your usual way, then tap **I paid another way · mark as paid**. Zotikos never holds or moves money."},{"type":"heading","text":"How the transfers are worked out"},{"type":"paragraph","text":"Each person's balance is what they paid for the group, minus their own shares, adjusted for payments already marked as paid. Zotikos first pairs anyone who owes exactly what someone else is owed, then has the person who owes most pay the person owed most, until everyone is at zero. A group of n people never needs more than n − 1 transfers."},{"type":"paragraph","text":"The banner at the top sums it up, for example “12 expenses, 9 IOUs, simplified to 4 transfers.”"},{"type":"heading","text":"The Settle up screen"},{"type":"list","ordered":false,"items":["**You pay**: who you owe, each with a **Pay** button.","**You get**: who owes you, each with **Got it**.","**Between others**: transfers between other people. Tap one to mark it paid.","**Net balances**: everyone's balance at a glance.","**Marked as paid**: recent payments, such as “paid you … by bank transfer”."]},{"type":"heading","text":"Paying someone"},{"type":"list","ordered":true,"items":["Tap **Pay** next to their name.","Choose **Bank transfer** to copy the amount and a reference for any bank app, or **Wise** or **PayPal**, which open in a new tab with the amount copied. You choose who to pay there.","Send the money.","Back in Zotikos, tap **I paid another way · mark as paid**, or **Paid in cash**."]},{"type":"paragraph","text":"When someone pays you, tap **Got it**, then **Mark as paid**."},{"type":"callout","title":"Before you mark it","text":"A payment marked as paid can't be undone in the app, so mark it once the money has actually been sent."},{"type":"paragraph","text":"Marked payments are listed under **Marked as paid** and in the ledger, and balances update for everyone. When nobody owes anything you'll see “Everyone's square. Nobody owes anything.”"},{"type":"heading","text":"If the trip's currency changed"},{"type":"paragraph","text":"Amounts left from before the change appear in their own card, “In {currency}”, marked as from before the currency changed. Tap **Pay it in** the new currency to move that amount onto the new line at today's rate, so it settles with everything else. Anyone on the trip can do this, while online."},{"type":"faq","items":[{"q":"What currency are the amounts in?","a":"The trip's currency, the one its balances are kept in. After a currency change, any older line is shown separately."},{"q":"Can I mark a payment offline?","a":"Yes. It syncs when you're back online."}]},{"type":"cta","title":"Nine IOUs. Four transfers.","text":"","label":"Open Zotikos","url":"https://zotikosapp.midnightpoetry.studio/"}]$c$::jsonb, false, $c$Settle up with fewer transfers | Zotikos$c$, $c$How Zotikos nets balances into few transfers, paying by bank transfer, Wise or PayPal, and marking payments as paid. Zotikos never holds your money.$c$, 'Midnight Poetry Studio', 'published'
