insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$use-the-map-tab$c$, $c$See where the group spent on the Map tab$c$, $c$Every place you've saved on a trip, pinned on a map with what was spent there. Everyone sees the places list; the map itself is part of Pro.$c$, $c$[{"type":"callout","title":"The short version","text":"Open a trip and tap **Map**. Free and guest accounts see the places list with what was spent at each. With Pro you also get the map, pins and a **Route** line. Add places to expenses to fill it up: see [Add where an expense was](/guides/zotikos/add-where-an-expense-was)."},{"type":"heading","text":"Where to find it"},{"type":"paragraph","text":"The Map tab is inside a trip: on a phone it's the middle tab (Overview, Ledger, **Map**, Settle up, Insights), on a tablet it's in the side bar, and on a computer it's in the sidebar between Ledger and Settle up. The Add expense button is hidden there."},{"type":"heading","text":"What the page shows"},{"type":"paragraph","text":"The header says “Map” with a line such as “Kyoto · 3 places · USD 120.00 of USD 200.00”: the places and what was spent at them, out of everything counted for the day you're looking at. Below it, Pro sees the map and everyone sees the list: “3 places”, most spent first (without the map it reads “Open any in Maps”)."},{"type":"list","ordered":false,"items":["**One pin per place**: expenses with the same name at the same saved spot share a pin (capitals and extra spaces are ignored). The same shop saved under two names, or at spots that round to different points (places are saved to about 10 metres by default), becomes two pins.","**Pin look**: its colour and icon show the category of the biggest expense there. A small number appears if there's more than one expense.","**Groups**: pins that would overlap join one dark circle showing how many places it holds. Tap it to zoom in until they come apart; at the closest zoom it opens the biggest place instead.","**No places yet?** You'll see “No places yet” and a button, **Add a place to an expense**, that opens the Ledger."]},{"type":"heading","text":"Tap a place"},{"type":"paragraph","text":"Tap a pin or a row in the list. The map moves to it if it isn't already in view, and the list switches to that place: its name, address and number of expenses, the total, and the expenses themselves, which you can tap like any Ledger row. Two buttons: **Open in Maps** (see [Open a place in your maps app](/guides/zotikos/open-a-place-in-your-maps-app)) and **All places** to go back. Tap empty map to clear the selection."},{"type":"heading","text":"Filter by day, draw a route"},{"type":"list","ordered":false,"items":["**Day**: choose **All days** or a day that has spending. A several-day stay counts in full on All days, and only that day's share on a single day.","**Route** (Pro): draws a dotted line through the places in the order they were first spent at. It needs at least two places, and it's a straight line between them, not driving directions."]},{"type":"paragraph","text":"Under the list, a line such as “3 expenses have no place · Add places” (“1 expense has no place” for one) counts the day's expenses that aren't pinned yet, and **Add places** opens the Ledger."},{"type":"heading","text":"Free and Pro"},{"type":"table","caption":"By default; Zotikos can change which plan gets what.","header":["Feature","Guest and Free","Pro"],"rows":[["Places list, totals, Day filter, expenses at each place","Yes","Yes"],["Open in Maps and Copy address","Yes","Yes"],["The map with pins and groups, and the Route toggle","A blurred stand-in with “See your trip on a map”","Yes"],["Search for a place, drop a pin, map previews","No","Yes"],["“Use where I am now”","Yes","Yes"]]},{"type":"faq","items":[{"q":"Why isn't my expense on the map?","a":"Only expenses with a place appear. Open the expense and add one, or tap **Add places** under the list."},{"q":"Why are there two pins for the same shop?","a":"Pins are grouped by name and saved spot. If the shop was saved under different names, or at spots that round to different points, each becomes its own pin."},{"q":"Does the map work offline?","a":"Your places list and pins come from the copy of the trip on your device, but the street map behind them doesn't load without a connection."}]},{"type":"cta","title":"See where it all went.","text":"","label":"Open Zotikos","url":"https://zotikosapp.midnightpoetry.studio/"}]$c$::jsonb, true, $c$See where the group spent on the Map tab | Zotikos$c$, $c$Use the Zotikos Map tab: find it, read the pins and groups, tap a place, filter by day, draw a route, and see what Free and Pro each get.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$map-and-places$c$
