insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$add-where-an-expense-was$c$, $c$Add where an expense was$c$, $c$Save a place with an expense so the group can find that ramen shop again. Use where you are now, or, with Pro, search or drop a pin. Open it in Maps from anywhere.$c$, $c$[{"type":"callout","title":"The short version","text":"On an expense, tap **Add where it was** under **Place**, then **Use where I am now**. On Free the place is added right away; with Pro you can nudge the pin on a map first, or search by name instead. Save the expense to keep it."},{"type":"heading","text":"Add a place"},{"type":"list","ordered":true,"items":["Add or open an expense. At the bottom, under **Place** (marked Optional), tap **Add where it was**.","In the sheet “Where was it?”, tap **Use where I am now**.","Allow location when your browser asks. Zotikos reads it only when you tap, never in the background.","On Free or a guest account, the place is added to the expense straight away and the sheet closes. With Pro, the spot appears on a map: move the map if it's a little off, then tap the confirm button."]},{"type":"paragraph","text":"Don't forget to save the expense. The place is part of it."},{"type":"heading","text":"Adding it later"},{"type":"paragraph","text":"“Use where I am now” saves where you are at that moment, not where the expense was. So use it while you're there. If you're adding a place afterwards, Pro lets you search for it and then move the map to fine-tune the pin (see [Search for a place or drop a pin](/guides/zotikos/search-for-a-place-or-drop-a-pin)). Without Pro, add it while you're at the spot."},{"type":"heading","text":"What you'll see"},{"type":"paragraph","text":"Once saved, the expense shows the place name and a line like “Nakagyo Ward, Kyoto · within 10 m” (the accuracy shows for places taken with **Use where I am now**). If Zotikos couldn't name the spot (for example, you were offline), it's called “Pinned location”, or “Dropped pin” for a pin you placed. In the Ledger the name appears on the expense's row."},{"type":"heading","text":"Change or remove it"},{"type":"list","ordered":false,"items":["Tap **Change** next to **Place** to pick a different place.","Tap the ✕ on the place card to remove it. It takes effect when you save the expense.","Tap **Maps** on the card to open it in a maps app (**Open in Maps** if you can't edit the expense; see [Open a place in your maps app](/guides/zotikos/open-a-place-in-your-maps-app))."]},{"type":"paragraph","text":"If you're not allowed to edit an expense, you can still open its place in Maps."},{"type":"heading","text":"Accuracy"},{"type":"paragraph","text":"Places are saved to about 10 metres by default (Zotikos can change this). If your phone's location is too rough, usually indoors or without a clear sky, Zotikos refuses it with “Your location is too rough to save. Try again outdoors, or search instead.” Step outside and try again. If it can't be found at all, see [Fix map and location problems](/guides/zotikos/fix-map-and-location-problems)."},{"type":"heading","text":"Who sees it"},{"type":"paragraph","text":"A place is part of the expense, so everyone on the trip can see it, and it's included in the CSV export (columns **Place**, **Place address**, **Latitude**, **Longitude**) and in **Download my data**. See [Your location, privacy and the map](/guides/zotikos/your-location-privacy-and-the-map)."},{"type":"faq","items":[{"q":"Is the place required?","a":"No. It's optional, and expenses without one just don't appear on the map."},{"q":"Can I add a place offline?","a":"Yes, “Use where I am now” can still get a location fix, and the place is saved with the expense when it syncs. Naming it needs a connection, so offline places, or ones Zotikos can't find a name for, are called “Pinned location”."}]},{"type":"cta","title":"So the group can find it again.","text":"","label":"Open Zotikos","url":"https://zotikosapp.midnightpoetry.studio/"}]$c$::jsonb, false, $c$Add where an expense was | Zotikos$c$, $c$Add a place to a Zotikos expense with Use where I am now, change or remove it, and see how location permission and accuracy work.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$map-and-places$c$
where p.slug = $c$zotikos$c$
