insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$search-for-a-place-or-drop-a-pin$c$, $c$Search for a place or drop a pin (Pro)$c$, $c$With Pro, find a shop or hotel by name, then move the map to place the pin exactly, and save it with the expense. Free and guest accounts can still use where they are now.$c$, $c$[{"type":"callout","title":"The short version","text":"In the **Where was it?** sheet, type a place or address into the search box and tap **Search**. Choose a result, drag the map so the pin sits on the spot, and tap the confirm button. This is part of Pro."},{"type":"heading","text":"Search"},{"type":"list","ordered":true,"items":["Open an expense, tap **Add where it was** (or **Change**).","Type a name or address into **Search a place or address**.","Tap **Search** (or press Enter). It searches only when you do, not as you type.","Tap a result. Each shows the name, the address and how far it is from your location fix or the map centre."]},{"type":"paragraph","text":"Up to eight results come back. If you see “Nothing found. Try the shop's name with the street or area.”, add the street, neighbourhood or city. Under the results a credit line names the service, “Search by Geoapify” or “Search by OpenStreetMap”, with “© OpenStreetMap contributors”. Zotikos tries Geoapify first and switches to OpenStreetMap by itself if needed."},{"type":"heading","text":"Fine-tune on the map"},{"type":"paragraph","text":"After you choose a result or a location fix, a map opens with a pin fixed in the middle. Move the map so the pin sits on the place (“Drag the map to move the pin”; with a mouse or trackpad it reads “Drag the map or click to move the pin”). The footer shows the name and address."},{"type":"list","ordered":false,"items":["Close to the result: the button reads **Use {name}** (or **Use this place** if the name is long).","Moved more than about 15 metres: it reads **Use this spot**, the footer says “Dropped pin” and “We'll name it from the map”, and Zotikos names it from the map once you tap (“Naming it…”)."]},{"type":"paragraph","text":"Then save the expense."},{"type":"heading","text":"Without Pro"},{"type":"paragraph","text":"Free and guest accounts see a teaser in the sheet: “Search or pick on a map” with a **PRO** tag. “Use where I am now” and **Open in Maps** are free for everyone."},{"type":"heading","text":"If search doesn't work"},{"type":"table","caption":"","header":["Message","What to do"],"rows":[["Place search is busy. Try again in a few seconds.","Wait a moment and search again."],["Place search isn't answering right now. Try again, or use where you are.","Try again shortly, or use where you are."],["Place search is switched off for now. Use where you are, or try again later.","Use where you are, or try again later."],["Too many tries. Please wait a moment.","You searched a lot in a short time; wait a minute."],["You're offline. Check your connection and try again.","Search needs a connection."]]},{"type":"faq","items":[{"q":"Does searching share my exact location?","a":"No. Zotikos's server receives your approximate position and rounds it to about 1 km before passing it on, along with what you typed and your language, to help rank nearby results. See [Your location, privacy and the map](/guides/zotikos/your-location-privacy-and-the-map)."},{"q":"Can I fix a place later?","a":"Yes. Open the expense, tap **Change** next to **Place** and pick another, then save."}]},{"type":"cta","title":"Pin it properly.","text":"","label":"Open Zotikos","url":"https://zotikosapp.midnightpoetry.studio/"}]$c$::jsonb, false, $c$Search for a place or drop a pin | Zotikos$c$, $c$With Zotikos Pro, search a place or address, move the pin on the map, and save it to an expense. Includes search tips and what the search messages mean.$c$, 'Midnight Poetry Studio', 'published'
