insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$open-a-place-in-your-maps-app$c$, $c$Open a place in your maps app$c$, $c$Any saved place can be opened in Apple Maps, Google Maps or your phone's maps app, or its address copied. It's free for everyone, even on expenses someone else added.$c$, $c$[{"type":"callout","title":"The short version","text":"Tap **Open in Maps** (or **Maps**) on any place, choose your maps app, and you're there. **Copy address** is in the same list. It's free for every plan."},{"type":"heading","text":"Where to find it"},{"type":"list","ordered":false,"items":["On the **Map** tab: choose a place, then **Open in Maps**. Even without Pro, the list lets you open any place.","On an expense's **Place** card: tap **Maps** (**Open in Maps** if you can't edit the expense).","On a computer, in an expense's side panel under **Place**: **Open in Maps**."]},{"type":"paragraph","text":"It works on places other travellers added, on expenses you're not allowed to edit, and on archived trips."},{"type":"heading","text":"Choose an app"},{"type":"paragraph","text":"A sheet titled “Open {place} in” lists what suits your device:"},{"type":"table","caption":"","header":["Device","Options"],"rows":[["Android","**Your maps app** (opens your default one) and **Google Maps**"],["iPhone and iPad","**Apple Maps** and **Google Maps**"],["Computer","**Google Maps**, **Apple Maps** and **OpenStreetMap** (in your browser)"]]},{"type":"paragraph","text":"The link uses the saved coordinates, so the pin lands exactly on the place."},{"type":"heading","text":"Copy the address"},{"type":"paragraph","text":"The last option, **Copy address**, copies the name, address and coordinates, for example “Nishikikoji-dori, Nakagyo Ward, Kyoto · 35.005, 135.7648”. You'll see “Address copied”. If copying fails, “Couldn't copy. Select the address instead.” appears."},{"type":"faq","items":[{"q":"Does this need Pro?","a":"No. Opening a saved place in a maps app, and copying its address, is free for everyone."},{"q":"Which map does it open?","a":"The one you choose in the sheet. Zotikos doesn't pick for you, and nothing is sent to that maps app until you open it."}]},{"type":"cta","title":"Find it again.","text":"","label":"Open Zotikos","url":"https://zotikosapp.midnightpoetry.studio/"}]$c$::jsonb, false, $c$Open a place in your maps app | Zotikos$c$, $c$Open a Zotikos place in Apple Maps, Google Maps, your Android maps app or OpenStreetMap, or copy its address. Free for every plan.$c$, 'Midnight Poetry Studio', 'published'
