insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$your-location-privacy-and-the-map$c$, $c$Your location, privacy and the map$c$, $c$When Zotikos asks for your location, what's saved, how precisely, who can see it, and what the map and search services get.$c$, $c$[{"type":"callout","title":"The short version","text":"Zotikos reads your location only when you tap **Use where I am now**, never in the background. A place is saved with an expense and seen by that trip's travellers. It isn't a location history."},{"type":"heading","text":"When it asks"},{"type":"paragraph","text":"Only when you tap **Use where I am now**. If you say no, nothing is read, and you can still search (with Pro) or add the expense without a place."},{"type":"heading","text":"What's saved"},{"type":"list","ordered":false,"items":["The place's name and an address line (street, area, city, country; up to three parts).","A point on the map, and how you chose it: where you were, search or the map.","For “where I am now”, how accurate the fix was."]},{"type":"paragraph","text":"All of it lives on the expense, so the trip's travellers can see it like the rest of the expense. It's also in that trip's CSV export and in **Download my data**. Remove a place with the ✕ on the expense; deleting the expense deletes it too. Zotikos keeps no per-person location history."},{"type":"heading","text":"How precisely"},{"type":"paragraph","text":"Your device rounds a location fix before sending it, and Zotikos's server rounds every saved place, whether it came from a fix, a search result or a map pick, to the same precision: by default about 10 metres. Zotikos can change that precision."},{"type":"heading","text":"What the map services receive"},{"type":"table","caption":"","header":["When","What goes out","To whom"],"rows":[["You search (Pro)","What you typed, your language and your position rounded to about 1 km, sent by Zotikos's server","Geoapify first, then OpenStreetMap as a backup"],["A place is named (where I am now, a dropped pin)","The point rounded to about 10 m, sent by Zotikos's server","The same two services"],["You view the map (Pro)","Your browser loads map tiles directly, so the provider sees your IP address and the area you view (only the app's address is sent as referrer)","Geoapify, or OpenStreetMap if Geoapify isn't answering"]]},{"type":"paragraph","text":"Search and naming go through Zotikos's server, so those services don't see your own IP address for them. Free and guest accounts never load map tiles, because they see no map."},{"type":"heading","text":"Other things to know"},{"type":"list","ordered":false,"items":["Map tiles aren't kept for offline use, and searching needs a connection.","The map credit at the bottom of the map names its source: “© OpenStreetMap”, or “Powered by Geoapify | © OpenStreetMap”.","If you stop having Pro, places you saved stay. You lose the map, search and previews, but **Open in Maps** keeps working."]},{"type":"faq","items":[{"q":"Can people outside the trip see my places?","a":"No. A place is part of the expense and is visible to the trip's travellers."},{"q":"Can I stop saving places?","a":"Yes. It's optional per expense. Just don't tap **Add where it was**, or remove a place with the ✕."}]},{"type":"cta","title":"Your trip, your places.","text":"","label":"Open Zotikos","url":"https://zotikosapp.midnightpoetry.studio/"}]$c$::jsonb, false, $c$Your location, privacy and the map | Zotikos$c$, $c$How Zotikos handles location: only when you tap, what a saved place contains, who sees it, and what Geoapify and OpenStreetMap receive for search and map tiles.$c$, 'Midnight Poetry Studio', 'published'
