insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$fix-map-and-location-problems$c$, $c$Fix map and location problems$c$, $c$Location blocked, “too rough”, search not answering, a blank map offline, or an empty Map tab: what each one means and what to try.$c$, $c$[{"type":"callout","title":"The short version","text":"Most problems are a blocked location permission, a weak signal indoors, or a feature that belongs to Pro. Find your message below."},{"type":"heading","text":"Location messages"},{"type":"table","caption":"","header":["You see","Try this"],"rows":[["Location is off for Zotikos. Turn it on in your browser or phone settings, then try again.","Allow location for Zotikos in your browser or phone settings, then tap **Use where I am now** again."],["Your location isn't available right now. Try again outdoors, or search instead.","Step outside or wait for a better signal. Search is a Pro feature."],["Finding your location took too long. Try again, or search instead.","Try again with a clearer view of the sky."],["Your location is too rough to save. Try again outdoors, or search instead.","Zotikos only saves a fix that's accurate enough. Go outdoors and retry."],["This browser can't share your location.","Use a different browser or device."]]},{"type":"heading","text":"Search messages"},{"type":"paragraph","text":"See the table in [Search for a place or drop a pin](/guides/zotikos/search-for-a-place-or-drop-a-pin). Searching is part of Pro, and every search needs a connection."},{"type":"heading","text":"The Map tab"},{"type":"table","caption":"","header":["What you see","Why","What to do"],"rows":[["A blurred picture and “See your trip on a map”","The map is part of Pro","The places list under it still works. Upgrade for the map."],["“No places yet”","No expense on the trip has a place","Tap **Add a place to an expense**."],["Pins but no streets","You're offline, or the map service isn't answering","Reconnect. The list and pins stay available."],["A place appears twice","It was saved under different names or spots","Edit one expense and choose the place again. With Pro, search for the same result; without Pro, each location fix is its own pin unless it lands on the same spot with the same name."],["An expense is missing","It has no place","Tap **Add places** under the list."],["Fewer places on one day","The Day filter is on","Choose **All days**."]]},{"type":"heading","text":"Still stuck?"},{"type":"paragraph","text":"Check you're online, reload the page, and try again. If a message isn't listed here, note exactly what it says before you contact Zotikos support."},{"type":"cta","title":"Back on the map.","text":"","label":"Open Zotikos","url":"https://zotikosapp.midnightpoetry.studio/"}]$c$::jsonb, false, $c$Fix map and location problems | Zotikos$c$, $c$Fix Zotikos location and map problems: location off, too rough, timeouts, search busy, blurred map on Free, blank map offline and expenses missing from the map.$c$, 'Midnight Poetry Studio', 'published'
