insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$guest-free-and-pro$c$, $c$Guest, Free and Pro: what each includes$c$, $c$Try Zotikos as a guest, keep using it free with an account, or go Pro for unlimited trips, every split method, the map and no sponsored cards.$c$, $c$[{"type":"callout","title":"The short version","text":"Free covers most trips: two active trips, equal and exact splits, settling up and ten receipt reads a month. Pro lifts most limits, adds the map and search, and removes the sponsored cards. Prices are shown in the app."},{"type":"heading","text":"What's included"},{"type":"table","caption":"Limits when this guide was written; they can change. The Upgrade screen lists the main Pro benefits.","header":["Feature","Guest","Free","Pro"],"rows":[["Active trips","1","2","Unlimited"],["Travellers per trip","4","8","50"],["Currencies per trip","2","5","Unlimited"],["Expenses per trip","100","500","Unlimited"],["Receipt reads","3 a day","10 a month","200 a month"],["Equal and exact splits","Yes","Yes","Yes"],["Percentages, shares, item by item","No","2 free tries per trip","Yes"],["Invite by link","No","Yes","Yes"],["Whole-trip budget","No","Yes","Yes"],["Insights: each day","No","Yes","Yes"],["Insights: exchange-rate gain/loss, card fees, by currency paid in","No","No","Yes"],["CSV exports","No","5 a month","Unlimited"],["Place: use where I am now, open in Maps","Yes","Yes","Yes"],["Place search, drop a pin, the map and Route","No","No","Yes"],["Sponsored cards","Yes","Yes","None"]]},{"type":"paragraph","text":"A trip's size limits (active trips, travellers, expenses, currencies, people per expense and invite links) come from the trip owner's plan. Split methods, receipt reads, exports, Insights, the map and sponsored cards follow your own plan."},{"type":"heading","text":"Sponsored cards"},{"type":"paragraph","text":"On guest and Free, a few cards marked “Sponsored” or “From Zotikos” appear on the trips list, trip home and Insights. They're served by Zotikos itself, with no third-party ad scripts, and never personalised. Each has **Remove ads with Pro**. Pro has none."},{"type":"heading","text":"Going Pro"},{"type":"list","ordered":true,"items":["Open **Account** and tap **Go Pro**. As a guest, add your email first; your guest trips come with you.","Choose **Yearly** or **Monthly**, then tap **Continue** (it shows the price).","Pay on Stripe's secure checkout. Zotikos never sees your card, and you'll see the exact price in your currency, with any tax, before you pay."]},{"type":"paragraph","text":"After paying, **Welcome to Pro** confirms it; this can take a few seconds. Have a promotion code? Enter it on the checkout page. If a free trial is on offer, checkout shows it there too."},{"type":"heading","text":"Your Pro tag"},{"type":"paragraph","text":"A small **Pro** tag shows on your own screens. People on your trips only see it if you turn on **Show my tag on shared trips** under **Your Pro** in Account. It's off by default. See [Your Pro tag and Welcome to Pro](/guides/zotikos/your-pro-tag-and-welcome-to-pro)."},{"type":"heading","text":"Managing or cancelling"},{"type":"paragraph","text":"In **Account**, under **Your Pro**, tap **Manage** to open Stripe's portal, or **Update card** if a payment failed. Pro renews automatically until you cancel, and you keep it until the end of the period you've paid for. Pro that Zotikos gave you has no Manage button."},{"type":"faq","items":[{"q":"Pro says “coming soon”.","a":"Pro isn't on sale yet. Everything on Free keeps working in the meantime."},{"q":"Can guests buy Pro?","a":"No, Pro needs an account. Add your email in **Account** and your guest trips come with you."}]},{"type":"cta","title":"Every trip, every split.","text":"","label":"See Pro","url":"https://zotikosapp.midnightpoetry.studio/upgrade"}]$c$::jsonb, false, $c$Guest, Free and Pro plans | Zotikos$c$, $c$Compare Zotikos guest, Free and Pro: trips, travellers, currencies, receipt reads, splits and map. Plus going Pro, managing it and cancelling.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$plans-and-account$c$
