insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$sign-in-security-and-your-data$c$, $c$Sign-in, security and your data$c$, $c$How signing in works, adding an authenticator app, your picture, name and home currency, keeping guest trips, downloading your data and deleting your account.$c$, $c$[{"type":"callout","title":"The short version","text":"Everything is in **Account**. Sign in with an email code or an authenticator app, and find **Download my data** and **Delete account** under **Privacy & data**."},{"type":"heading","text":"Signing in"},{"type":"paragraph","text":"Zotikos emails you a 6-digit code instead of asking for a password each time. A code works once, expires in 10 minutes, and asking for a new one stops the earlier ones working. Your password is the backup: tap **Use password instead**, or **Forgot your password?** to reset it with a code (**Email me a code**, then “Choose a new password” and **Save and sign in**)."},{"type":"paragraph","text":"Zotikos will never ask you for a code. If you get one you didn't ask for, you can ignore it. Under **Other devices**, **Sign out others** signs you out everywhere else (not shown on guest accounts)."},{"type":"heading","text":"Add an authenticator app"},{"type":"list","ordered":true,"items":["In **Account**, under **Sign-in & security**, tap **Set up** next to **Authenticator app**.","Tap **Continue** and scan the code with an app like 1Password, Google Authenticator or Authy, or type in the key.","Enter the 6-digit code it shows and tap **Turn on**."]},{"type":"paragraph","text":"Once it's on, this device offers your authenticator code instead of an email code (you can still tap **Email me a code instead**), and signing in with your password always asks for it as “One more lock”."},{"type":"heading","text":"Picture, name and home currency"},{"type":"list","ordered":false,"items":["**Picture**: tap it to choose **Take a photo**, **Choose a photo** or **Make an avatar**. Only people on your trips see it; photos are cropped and shrunk on your phone first. Guests can make an avatar, but photos need an account. See [Your picture and avatar](/guides/zotikos/your-picture-and-avatar).","**Name**: used when you make or join a trip. To change it on a trip you're already on, rename yourself on **People** (tap ⋯ next to your name).","**Home currency**: you can change it, but only new trips use it; trips you already have keep theirs, so nobody's balance shifts."]},{"type":"paragraph","text":"Under **This device**, **Theme** switches between Auto, Light and Dark, and **Offline copy** has a **Clear** button."},{"type":"heading","text":"Keep your guest trips"},{"type":"paragraph","text":"In **Account**, under **Keep your trips**, enter your email and tap **Send me a code**, then type the 6-digit code and tap **Keep my trips**. If that email already has a Zotikos account, you can **Sign in and bring my trips** into it or **Stay a guest**. If its active trips are full, a moved trip arrives archived."},{"type":"heading","text":"What Zotikos keeps"},{"type":"list","ordered":false,"items":["Your email, name, home currency and picture, and your trips: travellers, expenses, shares, payments and any places you saved.","Which “Needs a look” checks have been marked as fine, which everyone on the trip can see.","Receipt photos are never stored, only the details you save with an expense.","People on your trips see your name and picture, never your full email. Until you add a name, the part of your email before the @ is used.","Card details stay with Stripe.","No analytics and no third-party ad scripts.","To limit abuse, scrambled (hashed) versions of IP and email addresses, and short logs of receipt reads (outcome and timing only)."]},{"type":"heading","text":"Download your data"},{"type":"paragraph","text":"Next to **Download my data**, tap **JSON** for a file of every trip, expense and payment you can see. For one trip as a spreadsheet, use **Export as CSV** in its settings."},{"type":"heading","text":"Delete your account"},{"type":"paragraph","text":"Tap **Delete account**, type **delete** and tap **Delete my account**. This deletes the trips you own and removes you from other people's trips; your name stays on what you logged there, so their balances still add up. Any Pro subscription is cancelled first. It can't be undone, so download your data first if you want a copy."},{"type":"faq","items":[{"q":"I'm using Zotikos as a guest. How do I keep my trips?","a":"Under **Keep your trips** in **Account**, tap **Send me a code**, enter the code and tap **Keep my trips**."},{"q":"How do I contact Zotikos?","a":"Email zotikos-support@app.midnightpoetry.studio."}]},{"type":"cta","title":"Your trips, kept private.","text":"","label":"Open Zotikos","url":"https://zotikosapp.midnightpoetry.studio/"}]$c$::jsonb, false, $c$Sign-in, security and your data | Zotikos$c$, $c$Sign in with an email code, add an authenticator, set your picture and name, keep guest trips, download your data or delete your Zotikos account.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$plans-and-account$c$
where p.slug = $c$zotikos$c$
