insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$insights-on-a-trip$c$, $c$Insights: four questions about your trip$c$, $c$Insights answers four questions about a trip, for you and for the group: will we stay on budget, where did the money go, when was it spent and how did you pay.$c$, $c$[{"type":"callout","title":"The short version","text":"Open a trip and tap **Insights**. On a phone you see four tiles, one per question; tap one to open its answer. On a computer they're four tabs. Each answer shows the group's spending and your own share."},{"type":"heading","text":"Where to find it"},{"type":"paragraph","text":"Inside a trip, **Insights** is the last tab on a phone (Overview, Ledger, Map, Settle up, **Insights**), in the side rail on a tablet and in the sidebar on a computer. With more than one active trip, a **Trip** picker appears at the top (on a phone, above the list of four questions; on wide screens, above the chosen question, where it keeps your place). Outside a trip, the Insights tab shows all your trips instead: see [Insights across all your trips](/guides/zotikos/insights-across-all-your-trips)."},{"type":"heading","text":"The four questions"},{"type":"table","caption":"","header":["Question","What it tells you"],"rows":[["Will we stay on budget?","Whether the group is on track for the whole-trip budget, and how your own spending compares with your daily budget. See [Will we stay on budget?](/guides/zotikos/insights-will-we-stay-on-budget)."],["Where did the money go?","Each category, for the group and for you. See [Where and when the money went](/guides/zotikos/insights-where-and-when-the-money-went)."],["When was the money spent?","Each day, and, with Pro, what a day cost in each currency. See [Where and when the money went](/guides/zotikos/insights-where-and-when-the-money-went)."],["How did you pay?","Card or cash, and with Pro the cost of card fees and exchange rates. See [How did you pay?](/guides/zotikos/insights-how-did-you-pay)."]]},{"type":"paragraph","text":"On a phone, the tiles show a short answer first, such as “Food leads, 38%”. Tap one for the full answer and its cards; the back arrow returns you to the four questions. On screens 1024 pixels wide and up, most computers, they become four tabs and the first opens by default."},{"type":"heading","text":"Your share and the group"},{"type":"list","ordered":false,"items":["**Group** is the whole bill of every expense, in the trip's currency.","**Yours** is your own share of each expense. If you're not in an expense's split, it counts as zero for you.","**Stays and passes** that cover several days are spread evenly over their days in the Each day card and in your own daily average. Categories, the group's total and balances count them once.","**Older currency lines** (after a trip's currency was changed) count at the rate fixed when it changed."]},{"type":"paragraph","text":"Cards are tagged **You**, **Group** or **You + group** so you can tell which numbers you're reading."},{"type":"heading","text":"What each plan sees"},{"type":"table","caption":"Limits when this guide was written; they can change.","header":["Card","Guest","Free","Pro"],"rows":[["Will we stay on budget? (the over/under answer needs trip dates and a whole-trip budget)","Yes, without a budget","Yes","Yes"],["Where did the money go?","Yes","Yes","Yes"],["Each day","Locked","Yes","Yes"],["By currency paid in","No","No","Yes"],["Card or cash","Yes","Yes","Yes"],["Card fees; what the rates did since you paid","No","No","Yes"]]},{"type":"paragraph","text":"A locked card links to where you unlock it. Guests only need a free account for **Each day**; the other cards need Pro."},{"type":"heading","text":"Good to know"},{"type":"list","ordered":false,"items":["Everything is worked out on your device from the trip you have loaded, so Insights works offline. The only thing that needs rates is “What the rates did since you paid”.","“Today” is your device's date.","What's left to spend today is on the trip's **Overview**, and who owes whom is on **Settle up**, not here.","On guest and Free accounts, a sponsored card may appear at the bottom.","If any expenses may have been entered twice, a line such as “Includes 2 expenses that may be logged twice. Check them in the Ledger” links to [Needs a look: checks in the Ledger](/guides/zotikos/needs-a-look-checks-in-the-ledger). Nothing is removed from the numbers until someone fixes it."]},{"type":"faq","items":[{"q":"It says “Nothing to look at yet”.","a":"Insights needs at least one expense. Add one (or scan a receipt) and the answers appear."},{"q":"Does Insights open on an archived trip?","a":"Yes. Only the buttons that add expenses are hidden."}]},{"type":"cta","title":"Where did it all go?","text":"","label":"Open Zotikos","url":"https://zotikosapp.midnightpoetry.studio/"}]$c$::jsonb, false, $c$Insights: four questions about your trip | Zotikos$c$, $c$How Zotikos Insights works on a trip: the four questions, phone tiles and computer tabs, your share versus the group's, what each plan sees and offline use.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$insights-and-checks$c$
