insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$insights-where-and-when-the-money-went$c$, $c$Insights: where and when the money went$c$, $c$See each category for you and the group, which category leads, how a day cost, and, with Pro, what a day cost in each currency.$c$, $c$[{"type":"callout","title":"The short version","text":"**Where did the money go?** compares each category for the group and for you. **When was the money spent?** charts each day. Tap a category or a day for the biggest expenses behind it, with a link to the Ledger."},{"type":"heading","text":"Where did the money go?"},{"type":"paragraph","text":"The tile and the sentence name the leading category, for example “Food leads at 40% of day-to-day spending.” It also notes where your own mix differs (“Yours leans more to groceries (30% against 12%)”, when a category is 3 or more points bigger in yours) or that it's close to the group's. “Day-to-day spending” appears when stays are left out; otherwise it says “of spending”."},{"type":"list","ordered":false,"items":["The **Each category** card has a bar for the group and one for you in each category the trip has used, of the eight: Food, Groceries, Stay, Flights, Transport, Activities, Shopping and Other. Unused ones are named in a footnote. The bars share one scale, so you can compare them directly.","Percentages are whole numbers that add up to 100.","Tap a row to open it: “A day” (what it comes to a day, for the group and for you), the three biggest expenses, and **All … in the Ledger** to see them all."]},{"type":"heading","text":"Include stays"},{"type":"paragraph","text":"If the trip has a **Stay** expense, an **Include stays** switch appears. It's off by default (and resets to off each time you open the page) so one hotel bill doesn't hide everything else. It only affects the Stay category: a transport pass or another several-day expense is always counted."},{"type":"heading","text":"When was the money spent?"},{"type":"paragraph","text":"The **Each day** card has a bar per day: the group's total, with your part inside it. Tap a day (future days are greyed out) to see the group's and your total, what most of it was, and **See the day in the Ledger**. The back and forward arrows step through the days up to today. It opens on the priciest day so far."},{"type":"list","ordered":false,"items":["Stays and passes are spread evenly over their days.","The chart shows the trip's first 31 days at most. If the trip is missing a start or end date, it shows the 10 days up to today.","Each day needs an account: guests see it locked."]},{"type":"heading","text":"By currency paid in (Pro)"},{"type":"paragraph","text":"If the trip has expenses in more than one currency, Pro adds **By currency paid in**: for each currency, how many days it counted on, what a day cost and your part. It's a rough “where” based on the currency you paid in; no location is used. Free accounts see a teaser."},{"type":"faq","items":[{"q":"Why is Stay missing from the categories?","a":"**Include stays** is off. Switch it on to count them."},{"q":"Why doesn't a day add up to what I paid that day?","a":"A stay or pass counts a part on each of its days, so a day can include parts of bookings paid on other days."},{"q":"Is the category list the same as on the expense?","a":"Yes. Insights uses the same eight categories."}]},{"type":"cta","title":"See the shape of the trip.","text":"","label":"Open Zotikos","url":"https://zotikosapp.midnightpoetry.studio/"}]$c$::jsonb, false, $c$Insights: where and when the money went | Zotikos$c$, $c$Read the Zotikos categories and Each day cards: group versus your share, Include stays, the day-by-day chart, and By currency paid in with Pro.$c$, 'Midnight Poetry Studio', 'published'
