insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$insights-how-did-you-pay$c$, $c$Insights: how did you pay?$c$, $c$Card or cash, and with Pro, what card fees added and what exchange rates did since you paid. It's a guide, not an account statement.$c$, $c$[{"type":"callout","title":"The short version","text":"**Card or cash** is open to everyone. With Pro, **Paying abroad** adds what card fees cost you and what the exchange rates did since you paid. Card or cash and fees use what was recorded on each expense."},{"type":"heading","text":"Card or cash"},{"type":"paragraph","text":"The answer reads like “You paid 62% of your share by card, and card fees added …”. The **Card or cash** card has a bar for you (if you share any expenses) and one for the group, showing the card and cash amounts and percentages. Card or cash is the **Paid with** switch marked when each expense was added."},{"type":"heading","text":"Paying abroad (Pro)"},{"type":"paragraph","text":"This card appears when at least one expense is in a currency other than the trip's. Free and guest accounts see a teaser, “Card fees and exchange rates”."},{"type":"list","ordered":false,"items":["**Card fees**: your share of each card expense multiplied by the fee rate logged on it. Log a rate with **Card foreign-transaction fee** when you add a card expense (Pro). With none logged it says “none logged: add your card's foreign fee on an expense”.","**What the rates did since you paid**: one row per foreign currency with the average rate your share was counted at, today's reference rate and the difference in the trip's currency, plus an **Overall** line for two or more. A minus sign (in amber-brown) means paying when you did cost more than today's rate would; a plus (in green) means less."]},{"type":"callout","title":"What the numbers mean","text":"It isn't money lost. It compares the rate each expense was counted at with today's rate, and it uses Zotikos's daily reference rates, not your card's own rate. Fees are kept apart on purpose."},{"type":"paragraph","text":"If rates haven't loaded yet, for example offline on a new device, you'll see “Today's rates aren't loaded yet.”"},{"type":"faq","items":[{"q":"My bank's rate was different.","a":"Insights uses reference rates. For an exact figure, enter your own rate on the expense; see [How exchange rates work in Zotikos](/guides/zotikos/how-exchange-rates-work)."},{"q":"I'm on Free. Can I see fees someone else logged?","a":"No. The fee and rate rows follow your own plan."}]},{"type":"cta","title":"Know what the card cost.","text":"","label":"Open Zotikos","url":"https://zotikosapp.midnightpoetry.studio/"}]$c$::jsonb, false, $c$Insights: how did you pay? | Zotikos$c$, $c$Read the Zotikos card-or-cash split, card fees and exchange-rate gain or loss in Insights, and what the numbers do and don't mean.$c$, 'Midnight Poetry Studio', 'published'
