insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$insights-across-all-your-trips$c$, $c$Insights across all your trips$c$, $c$Your own spending across every trip this year: by month, by category, trip by trip, and what's still to settle. Only your share is counted.$c$, $c$[{"type":"callout","title":"The short version","text":"Outside a trip, tap **Insights** in the bottom bar (or sidebar). It's headed “All your trips · your share only” and adds up your own spending for the year. It's free on every plan."},{"type":"heading","text":"What it shows"},{"type":"table","caption":"","header":["Tile","Meaning"],"rows":[["Your spend","Your share this year, and how many trips it's across."],["Days away","Days of your trips inside this year, up to today. A trip with no start date adds none."],["Per day away","Your spend divided by days away."],["Countries","How many different countries you set on your trips (**Pick one in trip settings** if none)."],["Still to settle","“All square”, or what you owe or are owed on open trips, any year; with mixed currencies, how many trips are open. Archived trips are left out."]]},{"type":"list","ordered":false,"items":["**Spend by month**: 12 bars, Jan to Dec, stacked and coloured by trip.","**Where your money went**: a bar and list of categories with percentages and amounts.","**Trips compared**: your share this year, per day, the trip's whole group total and days, and its status (On the road, In 5d or Soon, To settle, Settled). Tap a row for that trip's Insights."]},{"type":"paragraph","text":"With more than one trip, the picker **Open a trip's insights** jumps straight to one. With none, you'll see “Insights start with a trip”."},{"type":"heading","text":"How it's counted"},{"type":"list","ordered":false,"items":["**Only your share.** Nothing about anyone else is included.","**Your home currency.** Spend, months, categories and per-day figures are shown in it; other currencies are converted at today's rate, not the rate on the day. If a currency has no rate, that trip is left out and a note says which (“Leaves out …”). Trips compared shows each trip's group total in its own currency.","**The calendar year.** Only expenses dated this year count.","**A stay counts when it starts.** Unlike trip Insights, a several-day expense isn't spread: it lands in the month it begins.","**Archived trips** still count in the spend, but not in Still to settle."]},{"type":"paragraph","text":"Guests see the trips on their guest account. Offline, it uses the last saved copy; if the summary has never loaded, Your spend shows “—” and the charts say “Adding it up…”."},{"type":"faq","items":[{"q":"Why doesn't a trip's total match its own Insights?","a":"All-trips Insights counts only your share, in your home currency, at today's rate, and dates a stay by its first day. A trip's own Insights shows the group too and spreads stays over their days."}]},{"type":"cta","title":"Your year, at a glance.","text":"","label":"Open Zotikos","url":"https://zotikosapp.midnightpoetry.studio/"}]$c$::jsonb, false, $c$Insights across all your trips | Zotikos$c$, $c$Use the Zotikos all-trips Insights: your year at a glance, spend by month and category, trips compared, and how currencies and archived trips are counted.$c$, 'Midnight Poetry Studio', 'published'
