insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$needs-a-look-checks-in-the-ledger$c$, $c$Needs a look: checks in the Ledger$c$, $c$Zotikos quietly checks for expenses that may be logged twice, typed rates that look off and receipts that don't add up. They're only checks: nothing changes until someone edits an expense.$c$, $c$[{"type":"callout","title":"The short version","text":"When something may be wrong, the Ledger shows a **Needs a look** card. Open it, then fix the expense, or tap **They're different**, **Keep typed rate** or **Keep this total** to mark it fine. Marking changes no amounts or balances."},{"type":"heading","text":"Where you'll see it"},{"type":"list","ordered":false,"items":["A **Needs a look** card at the top of the Ledger, with a number and a summary such as “1 maybe logged twice · 2 typed rates”.","A **Twice?** chip on Ledger rows that may be duplicates.","A line in Insights: “Includes 2 expenses that may be logged twice. Check them in the Ledger”."]},{"type":"paragraph","text":"The Needs a look page says how many to check (“2 to check on Kyoto. Anyone who can edit them can sort them out.”) or “All sorted.” It's available to every plan, and everyone on the trip can see it."},{"type":"heading","text":"The three checks"},{"type":"table","caption":"","header":["Check","It's flagged when","Buttons"],"rows":[["Maybe logged twice","Two expenses have the same day, currency, amount and category, and were paid by different people or added within 30 minutes of each other","**They're different**"],["Rate typed in","A rate you typed for a foreign currency is more than 3% above or below that day's reference rate","**Keep typed rate**, **Change the rate**"],["Doesn't add up","A read receipt's items (or subtotal) plus charges don't match the total kept as the expense amount","**Keep this total**, **Open details**"]]},{"type":"heading","text":"Maybe logged twice"},{"type":"paragraph","text":"The card shows both expenses, who paid and when each was added. If it was one purchase, open one and remove it (if you're allowed to delete it): shares and balances update for everyone. If they're genuinely separate (two same-priced coffees, say), tap **They're different**. Descriptions aren't compared, so look closely. Only pairs are flagged: a third identical expense isn't."},{"type":"heading","text":"A rate that looks off"},{"type":"paragraph","text":"It compares your typed rate with the reference rate for that day, or the most recent earlier one if that day has none (a weekend, say). The card says “A card or exchange-counter rate can be right, so this is only a check.” Tap **Keep typed rate** if it's right, or **Change the rate** to edit the expense. If a day's reference rate couldn't be loaded, for example offline, you'll see a note that some typed rates weren't checked; they're checked once it is."},{"type":"heading","text":"A receipt that doesn't add up"},{"type":"paragraph","text":"It shows what the items and charges come to against the total kept, and notes if two digits may be swapped. Tap **Keep this total** if the total is right, or **Open details** to fix it."},{"type":"heading","text":"Marked as fine"},{"type":"paragraph","text":"Marking a check as fine hides it for everyone on the trip. It changes no expense, amount or balance. Under **Marked as fine** you'll see who did it and when (“You marked it fine”, or the traveller's name). **Undo** brings it back if the problem still holds. The mark stays if the expense is edited, and goes if it's deleted."},{"type":"heading","text":"Who can sort them"},{"type":"paragraph","text":"You can mark or undo a check if you can edit at least one of the expenses involved: you added it, you're an owner or co-owner, or the trip lets everyone edit. Otherwise you see just “Only whoever added it, or the trip's owners, can sort this one.” instead of the buttons. On an archived trip everyone sees “This trip is archived.” Marking and undoing need a connection (“You're offline. Try again once you're back online.”)."},{"type":"faq","items":[{"q":"Why does the Ledger count differ from Insights?","a":"The Ledger counts checks, so a pair is one. Insights counts expenses, so the same pair is two, and it only counts possible duplicates."},{"q":"Did marking it fine delete anything?","a":"No. It only hides the card."}]},{"type":"cta","title":"Catch the doubles.","text":"","label":"Open Zotikos","url":"https://zotikosapp.midnightpoetry.studio/"}]$c$::jsonb, false, $c$Needs a look: checks in the Ledger | Zotikos$c$, $c$How the Zotikos Needs a look checks work: possible duplicates, a rate far from the day's, a receipt that doesn't add up, and Marked as fine with Undo.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$insights-and-checks$c$
where p.slug = $c$zotikos$c$
on conflict (product_id, slug) do update set category_id = excluded.category_id, title = excluded.title, standfirst = excluded.standfirst, blocks = excluded.blocks, start_here = excluded.start_here,
  meta_title = excluded.meta_title, meta_description = excluded.meta_description
  where public.guides.updated_by is null;

insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$your-picture-and-avatar$c$, $c$Your picture and avatar$c$, $c$Add a photo or make an avatar so the people on your trips see you. It's only shown to them, and it can be removed any time.$c$, $c$[{"type":"callout","title":"The short version","text":"In **Account**, tap your picture (or the **Picture** row) to open “Your picture”. Choose **Take a photo**, **Choose a photo** or **Make an avatar**. Only people on your trips can see it."},{"type":"heading","text":"Open the picture sheet"},{"type":"list","ordered":false,"items":["Tap the round picture at the top of **Account**.","Or tap **Change** (or **Add**) on the **Picture** row, “Shown to people on your trips”."]},{"type":"paragraph","text":"The sheet shows your current picture and these options:"},{"type":"list","ordered":false,"items":["**Take a photo**: with your camera.","**Choose a photo**: from your library. A Memoji works if you've saved it as a photo.","**Make an avatar** (or **Change your avatar**): “Pick a face, hair and colours”.","**Use your initial**: appears once you have a picture or avatar. It removes it straight away, with no confirmation, and you'll see “Picture removed”."]},{"type":"paragraph","text":"Guests can make an avatar, but **Take a photo** and **Choose a photo** are switched off (“Needs an account (keep your trips first)”). Add your email under **Keep your trips** first."},{"type":"heading","text":"A photo"},{"type":"paragraph","text":"After you pick a photo, a round window opens: “Move and zoom”. Drag to place it, pinch or use the zoom slider (up to 4×), then tap **Use**. It's saved small, 256 × 256 pixels, as a plain image, so location and camera details are left out. You'll see “Photo saved”. If a photo can't be opened, try a JPEG, PNG or HEIC photo from your library."},{"type":"heading","text":"An avatar"},{"type":"paragraph","text":"**Make an avatar** has five tabs and a **Shuffle** button:"},{"type":"table","caption":"","header":["Tab","Choices"],"rows":[["Skin","Six skin tones, from Light to Deepest"],["Hair","Short, Side part, Curly, Bun, Bob, Long or Buzz, plus a hair colour"],["Extras","None, Glasses, Sunglasses, Sun hat, Beanie or Neck pillow"],["Mood","Smile, Calm or Wink"],["Colour","Rose, Sky, Sage, Sand, Lilac or Lagoon"]]},{"type":"paragraph","text":"Tap **Use this avatar** to save it (“Avatar saved”). On a trip, everyone gets a different colour, so yours can change there. Avatars are free on every plan."},{"type":"heading","text":"Where it shows and who sees it"},{"type":"list","ordered":false,"items":["On the trips list, People, the Ledger, Settle up and when you add expenses.","Only you and the people you share a trip with can see it. It's never public and has no link to share.","Travellers added by name only, with no account, show a coloured initial. So do you, until you add a picture."]},{"type":"heading","text":"Removing it"},{"type":"paragraph","text":"Tap **Use your initial** to remove it. Deleting your account deletes your picture too, and **Download my data** includes it. Saving a picture needs a connection."},{"type":"faq","items":[{"q":"Why can't I pick a photo as a guest?","a":"Photos need an account. Add your email under **Keep your trips** in Account, then try again."},{"q":"Do others see my new picture straight away?","a":"Photos refresh on their devices as they sync, so it may take a moment."}]},{"type":"cta","title":"Show your face, or a made-up one.","text":"","label":"Open Zotikos","url":"https://zotikosapp.midnightpoetry.studio/"}]$c$::jsonb, false, $c$Your picture and avatar | Zotikos$c$, $c$Add a photo or make an avatar in Zotikos, how photos are cropped and shrunk, who can see your picture, and how to remove it.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$plans-and-account$c$
where p.slug = $c$zotikos$c$
