  where public.guides.updated_by is null;

insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$your-pro-tag-and-welcome-to-pro$c$, $c$Your Pro tag and Welcome to Pro$c$, $c$What the Pro tag and the Pro trial chip look like, who can see your tag, what Welcome to Pro waits for, and how to manage or update your card.$c$, $c$[{"type":"callout","title":"The short version","text":"After you go Pro you'll see a small **Pro** tag on your Account. Others only see it if you turn on **Show my tag on shared trips** in Account › **Your Pro**; it's off by default."},{"type":"heading","text":"Your tag"},{"type":"paragraph","text":"The tag is solid for Pro, and a dashed outline during a trial, with a chip such as “Pro trial · 6 days”. You'll see it on your Account header, the Account tab and your name in the sidebar. If a payment is failing, the tag is hidden even though Pro keeps working; Account says what to fix."},{"type":"heading","text":"Who else can see it"},{"type":"paragraph","text":"Nobody, unless you switch on **Show my tag on shared trips** under **Your Pro** (“On: people on your trips see your Pro tag” / “Off: only you see that you're Pro”). You'll see “People on your trips can see your Pro tag”, or “Your Pro tag is private again”. They see it only next to your name on People and in the Group balances card on a trip's Overview (on computers), never in the Ledger or Settle up. They can't tell trial from paid. You need an account and a connection to change it."},{"type":"heading","text":"Welcome to Pro"},{"type":"paragraph","text":"After checkout, **Welcome to Pro** waits for Stripe to confirm your payment: “Confirming your payment…” for a few seconds. When Pro is on, it says “Welcome to Pro” and lists what's now on. For a trial it says when it runs until (“Cancel any time in Account.”)."},{"type":"list","ordered":false,"items":["**Almost there**: if it takes about 30 seconds, you'll see “Stripe is still confirming your payment. Pro switches on by itself as soon as it does, so you can carry on.” Tap **Check again** or **Back to my trips**.","**Your payment didn't go through**: tap **Go to Account** and update your card to keep Pro."]},{"type":"heading","text":"Your Pro in Account"},{"type":"paragraph","text":"Under **Your Pro**, the row reads “Trial ends …”, “Renews …” or, if Zotikos gave you Pro, “Given by Zotikos, until …”. **Manage** opens Stripe's secure billing portal, where you manage your subscription and card. If a payment failed, the button reads **Update card**. Pro that Zotikos gave you has no Manage button."},{"type":"heading","text":"A trial"},{"type":"paragraph","text":"If a free trial is on offer, it begins when you check out. Each account can have one. During it you have the full Pro plan and the chip shows how many days are left. See [Guest, Free and Pro](/guides/zotikos/guest-free-and-pro) for what Pro includes."},{"type":"faq","items":[{"q":"Why did my tag disappear?","a":"While a payment is failing the tag is hidden, but Pro keeps working. Tap **Update card** in Account."},{"q":"Can a guest turn on the tag?","a":"No. It needs an account."}]},{"type":"cta","title":"Every trip, every split.","text":"","label":"See Pro","url":"https://zotikosapp.midnightpoetry.studio/upgrade"}]$c$::jsonb, false, $c$Your Pro tag and Welcome to Pro | Zotikos$c$, $c$Understand the Zotikos Pro tag and trial chip, show or hide your tag on shared trips, the Welcome to Pro screen, and Manage or Update card.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$plans-and-account$c$
where p.slug = $c$zotikos$c$
on conflict (product_id, slug) do update set category_id = excluded.category_id, title = excluded.title, standfirst = excluded.standfirst, blocks = excluded.blocks, start_here = excluded.start_here,
